window.products.push({"id":789230,"name":"Valeron Palermo Tencel Modal-Performance, Cooling, Silky Soft-Solid Diamond Stitched Quilt, King, Charcoal","category":"homeandappliances","retail price":84.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/81x7-oU6leL._AC_SL1500_.jpg","description":"Layer your bed in ultimate luxury with the Palermo quilt by Valeron. 100% TENCEL Modal, this classic and elegant quilt is crafted with both luxury and performance in mind: silky soft, breathable, moisture wicking, cool to the touch, and made from a fiber that is sustainably sourced. Complete your bed with matching shams, sold separately. TENCEL Modal is made from a blend of hardwoods including beech trees, all of which are a natural and renewable raw material sustainably sourced from Austria and other neighboring countries.","images":["https://m.media-amazon.com/images/I/81x7-oU6leL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Valeron","source_asin":"B08YKGJGMW","category_path":"Home & Kitchen"},"sku":"BM-789230","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B08YKGJGMW","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B08YKGJGMW","price_pending":true,"merchant_ready":false});
